 @page "/notifications"
 @rendermode InteractiveServer
 @using BlazorApp.Services
 @inject NotificationService NotificationService
 @implements IDisposable

 <PageTitle>Notifications</PageTitle>

 <h1>Notifications <span class="badge bg-primary">@(NotificationList?.Count ?? 0)</span></h1>

 @if (NotificationList is null)
 {
     <p>Loading...</p>
 }
 else if (NotificationList.Count == 0)
 {
     <p>No notifications.</p>
 }
 else
 {
     <ul class="list-group">
         @foreach (var n in NotificationList.OrderByDescending(x => x.Timestamp))
         {
             <li class="list-group-item">
                 <strong>@n.Message</strong>
                 <small class="text-muted ms-2">@n.Timestamp.ToString("g")</small>
             </li>
         }
     </ul>
 }

 @code {
     private CancellationTokenSource? _cts;

     [PersistentState]
     public List<Notification>? NotificationList { get; set; }

     protected override async Task OnInitializedAsync()
     {
         // Only fetch if not restored from prerender state
         NotificationList ??= await NotificationService.GetNotificationsAsync();
     }

     protected override void OnAfterRender(bool firstRender)
     {
         if (firstRender)
         {
             // Start polling only after the component is interactive (not during prerender)
             _cts = new CancellationTokenSource();
             _ = PollForNotificationsAsync(_cts.Token);
         }
     }

     private async Task PollForNotificationsAsync(CancellationToken ct)
     {
         while (!ct.IsCancellationRequested)
         {
             await Task.Delay(5000, ct).ConfigureAwait(false);

             if (ct.IsCancellationRequested) break;

             var lastId = NotificationList?.Count > 0
                 ? NotificationList.Max(n => n.Id)
                 : 0;

             var newer = await NotificationService.GetNotificationsSinceAsync(lastId);
             if (newer.Count > 0)
             {
                 await InvokeAsync(() =>
                 {
                     NotificationList ??= new();
                     NotificationList.AddRange(newer);
                     StateHasChanged();
                 });
             }
         }
     }

     public void Dispose()
     {
         _cts?.Cancel();
         _cts?.Dispose();
     }
 }

